// LAB: Flush the final partial buffer
// Combine characters into batches of four, then forward any remaining suffix at the end. Do not count an empty final flush as a data transfer.
// This starter verifies the original example. Extend it to satisfy the lab checks.
#include <cassert>
#include <iostream>
#include <string>

int main() {
    std::string pending, destination;
    int flushes = 0;
    const auto flush = [&] { destination += pending; pending.clear(); ++flushes; };
    pending += "AB";
    pending += "CD";
    if (pending.size() >= 4) flush();
    pending += "E";
    flush();
    std::cout << destination << " flushes=" << flushes << '\n';
    assert(destination == "ABCDE" && flushes == 2);
}

#include <cassert>
#include <iostream>
#include <string>
#include <utility>

std::pair<std::string,unsigned> buffered(const std::string& input) {
    std::string pending, output; unsigned flushes = 0;
    const auto flush = [&] {
        if(pending.empty()) return;
        output += pending; pending.clear(); ++flushes;
    };
    for(char ch : input) { pending += ch; if(pending.size() == 4) flush(); }
    flush();
    return {output,flushes};
}

int main() {
    const auto result = buffered("ABCDE");
    assert(result.first == "ABCDE" && result.second == 2);
    assert(buffered("ABCD").second == 1 && buffered("").second == 0);
    std::cout << result.first << " batches=" << result.second << '\n';
}

